function spawnWithTimeout(options) {
  return new Promise((resolve2) => {
    let child;
    let timeoutId;
    let killed = false;
    let stdout = "";
    let stderr = "";
    let finished = false;
    const onAbort = () => {
      killTree();
      finish({ stdout, stderr, exitCode: null, timedOut: true });
    };
    const finish = (result) => {
      if (finished) return;
      finished = true;
      if (timeoutId) clearTimeout(timeoutId);
      options.signal?.removeEventListener("abort", onAbort);
      resolve2(result);
    };
    const killTree = () => {
      if (!child || killed) return;
      killed = true;
      try {
        if (process.platform === "win32" && child.pid) {
          spawn("taskkill", ["/pid", String(child.pid), "/T", "/F"], { windowsHide: true }).unref();
        } else {
          child.kill("SIGTERM");
        }
      } catch {
      }
    };
    if (options.signal?.aborted) {
      finish({ stdout, stderr, exitCode: null, timedOut: true });
      return;
    }
    if (options.signal) {
      options.signal.addEventListener("abort", onAbort, { once: true });
    }
    try {
      child = spawn(options.command, options.args, {
        cwd: options.cwd,
        windowsHide: options.windowsHide ?? true,
        env: options.env ?? process.env
      });
    } catch (error) {
      finish({ stdout: "", stderr: String(error), exitCode: 1, timedOut: false });
      return;
    }
    child.stdout?.on("data", (data) => {
      stdout += data.toString();
    });
    child.stderr?.on("data", (data) => {
      stderr += data.toString();
    });
    child.on("error", (error) => {
      finish({ stdout, stderr: error.message, exitCode: 1, timedOut: false });
    });
    child.on("close", (code) => {
      finish({ stdout, stderr, exitCode: code, timedOut: false });
    });
    if (options.timeoutMs && options.timeoutMs > 0) {
      timeoutId = setTimeout(() => {
        killTree();
        finish({ stdout, stderr, exitCode: null, timedOut: true });
      }, options.timeoutMs);
    }
  });
}
function checkGitResult(result) {
  if (result.timedOut) return { content: "Git command timed out after 120 seconds.", is_error: true };
  if (result.exitCode !== 0) return { content: result.stderr || result.stdout, is_error: true };
  return null;
}
async function runGitCommand(args) {
  const { command, cwd = process.cwd(), flags = [], timeoutMs = 12e4, signal } = args;
  const result = await spawnWithTimeout({
    command: "git",
    args: [command, ...flags],
    cwd,
    timeoutMs,
    signal
  });
  return {
    stdout: result.stdout,
    stderr: result.stderr,
    exitCode: result.exitCode ?? 0,
    timedOut: result.timedOut
  };
}
