function findGameStrategy(gameName) {
  const lower = gameName.toLowerCase();
  for (const [key, strategy] of Object.entries(GAME_STRATEGIES)) {
    if (lower.includes(key)) return strategy;
  }
  return GAME_STRATEGIES.generic;
}
